const ctxBar = (pct: number, width: number): string => {
  const filled = Math.round((width * pct) / 100)
  return '█'.repeat(filled) + '░'.repeat(Math.max(0, width - filled))
}

const STATUS_GLYPH: Record<string, string> = { running: '●', done: '✓', failed: '✗', planned: '◷' }

// Background sessions: `claude agents --json` plus one `git worktree list` per poll, so the branch costs no
// extra call per session. Runs only while the pane is open or a flow's bar is up (the clock in session.start).
let isPolling = false

async function pollBg($: EngineInterface): Promise<void> {
  if (isPolling) return
  isPolling = true
  try {
    const self = await $.session.id()
    const repo = await $.session.repo()
    const ran = await $.process.run(['claude', 'agents', '--json'], { timeoutMs: 10_000 })
    if (ran.exitCode !== 0) return
    const tree = repo ? await $.process.run(['git', '-C', repo.root, 'worktree', 'list', '--porcelain'], { timeoutMs: 5000 }).catch(() => null) : null
    const trees = tree?.exitCode === 0 ? parseWorktrees(tree.stdout) : []
    const launched = await read($, launches)
    const list: BgSession[] = parseAgents(ran.stdout)
      .filter(a => a.sessionId !== self && a.kind !== 'interactive' && isRelated(a, trees, launched))
      .slice(0, 24)
      .map(a => {
        const l = launched[a.name.toLowerCase()]
        return { id: a.sessionId, name: a.name, state: bgState(a), tier: tierFor(l), model: l?.model, effort: l?.effort, branch: branchOf(a, trees), cwd: a.cwd }
      })
    const prev = await read($, bg)
    if (JSON.stringify(prev) !== JSON.stringify(list)) await update($, bg, () => list)
  } catch {
    // The list stays as it was; the next poll tries again.
  } finally {
    isPolling = false
  }
}

// Opens the agents pane, or closes it when it is up; true when it ends up open.
async function togglePane($: EngineInterface): Promise<boolean> {
  const isOpen = (await $.ui.panes()).some(p => p.id === PANE)
  if (isOpen) {
    await $.ui.close({ id: PANE })
    return false
  }
  const at = await $.clock.now()
  await update($, now, () => at)
  await $.ui.open({ id: PANE, title: tr().pane })
  await pollBg($)
  return true
}

async function autoOpen($: EngineInterface, key: string): Promise<void> {
  const p = await read($, panel)
  if (p.autoOpenedFor === key) return
  await update($, panel, prev => ({ ...prev, autoOpenedFor: key }))
  void $.ui.open({ id: PANE, title: tr().pane })
  void pollBg($)
}

// The view pane re-reads its target every VIEW_EVERY_MS while shown: an agent's transcript from this
// session; a background session's transcript file (its tail), else its terminal through `claude logs`.
let isViewing = false
// Where each background session's transcript was found, and its mtime at the last read (skip when unchanged).
const transcriptPaths = new Map<string, string>()
let lastRead = ''

// Bytes from the end: screenshots make single entries hundreds of KB, so a line count would see too little.
const TAIL_BYTES = 3_500_000

async function findTranscript($: EngineInterface, id: string, cwd?: string): Promise<string | null> {
  const known = transcriptPaths.get(id)
  if (known) return known
  const config = await $.env.get('CLAUDE_CONFIG_DIR')
  const home = (await $.env.get('USERPROFILE')) || (await $.env.get('HOME'))
  const root = `${config || `${home}/.claude`}/projects`
  // The folder is the cwd with every other character a dash; a scan covers a name the engine shortened.
  const guess = cwd ? [cwd.replace(/[^a-zA-Z0-9]/g, '-')] : []
  const dirs = [...guess, ...(await $.fs.list(root).catch(() => [])).filter(d => d.kind === 'dir').map(d => d.name)]
  for (const d of dirs) {
    const path = `${root}/${d}/${id}.jsonl`
    if (await $.fs.exists(path)) {
      transcriptPaths.set(id, path)
      return path
    }
  }
  return null
}

// The file's last TAIL_BYTES: read whole when small, else `tail -c` (a seek in PowerShell on Windows, raw
// bytes so no code page touches them); a file read rejects over 4 MiB. Null when unchanged since the last read.
async function readTail($: EngineInterface, path: string): Promise<string | null> {
  const st = await $.fs.stat(path)
  const stamp = `${path}:${st.mtimeMs}:${st.size}`
  if (stamp === lastRead) return null
  let text: string
  if (st.size <= TAIL_BYTES) text = await $.fs.read(path)
  else {
    const isWindows = /^[A-Za-z]:/.test(path)
    const ps =
      `$f=[IO.File]::Open('${path.replace(/'/g, "''")}','Open','Read','ReadWrite'); $n=[Math]::Min($f.Length,${TAIL_BYTES}); ` +
      `[void]$f.Seek(-$n,'End'); $b=New-Object byte[] $n; [void]$f.Read($b,0,$n); $f.Close(); ` +
      `$o=[Console]::OpenStandardOutput(); $o.Write($b,0,$n); $o.Flush()`
    const argv = isWindows ? ['powershell', '-NoProfile', '-Command', ps] : ['tail', '-c', String(TAIL_BYTES), path]
    const ran = await $.process.run(argv, { timeoutMs: 10_000 })
    if (ran.exitCode !== 0) throw new Error(ran.stderr.trim() || 'tail failed')
    text = ran.stdout
  }
  lastRead = stamp
  return text
}

async function refreshView($: EngineInterface): Promise<void> {
  const v = await read($, view)
  if (!v || isViewing) return
  isViewing = true
  try {
    let lines: ViewLine[]
    let source: 'transcript' | 'logs' = 'transcript'
    if (v.kind === 'agent') {
      const found = await $.session.messages({ agentId: v.id })
      lines = Array.isArray(found) ? messageLines(found) : [{ kind: 'error', text: found.deny }]
    } else {
      const path = await findTranscript($, v.id, v.cwd)
      const text = path ? await readTail($, path) : undefined
      if (text === null) return // unchanged
      if (text !== undefined) lines = messageLines(transcriptMessages(text))
      else {
        // `claude logs` takes the short id `claude agents` prints, not the session id.
        const ran = await $.process.run(['claude', 'logs', v.id.slice(0, 8)], { timeoutMs: 10_000 })
        lines = ran.exitCode === 0 ? logLines(ran.stdout) : [{ kind: 'error', text: `claude logs: ${clean(ran.stderr || ran.stdout).trim()}` }]
        source = 'logs'
      }
    }
    let isChanged = false
    await update($, view, prev => {
      isChanged = !!prev && prev.id === v.id && (prev.source !== source || JSON.stringify(prev.lines) !== JSON.stringify(lines))
      return isChanged && prev ? { ...prev, lines, source } : prev
    })
    if (isChanged && (await read($, viewFollow))) await $.ui.scroll({ in: VIEW_PANE, to: 'end' }).catch(() => undefined)
  } catch (err) {
    const lines: ViewLine[] = [{ kind: 'error', text: clean(String(err)) }]
    await update($, view, prev => (prev && prev.id === v.id ? { ...prev, lines } : prev))
  } finally {
    isViewing = false
  }
}

async function openView($: EngineInterface, raw: ViewTarget): Promise<void> {
  // A session names itself: the name reaches the tab title and the header, so it is cleaned too.
  const target = { ...raw, name: clean(raw.name) }
  lastRead = ''
  await update($, view, () => ({ ...target, lines: [] }))
  await update($, viewFollow, () => true)
  await $.ui.open({ id: VIEW_PANE, title: target.name.slice(0, 40) || target.id.slice(0, 8), focus: true, closeOnEscape: true })
  await refreshView($)
}

export const register: Register = (on, options) => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    lang = await detectLang($, options.language)
    await $.tool.register({
      name: 'progress',
      description:
        'Report /savvy-flow progress to the progress bar above the prompt and the agents panel. ' +
        'Call it after presenting the plan (title, total, tasks, phase "delegate"), each time a task is accepted (done), ' +
        'when switching phase or re-planning (tasks), and once at the end with finished: true. Fields left out keep their previous value.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Short name of the overall task, a few words.' },
          total: { type: 'integer', minimum: 0, description: 'Number of planned worker tasks.' },
          done: { type: 'integer', minimum: 0, description: 'Number of tasks accepted after review.' },
          phase: { type: 'string', enum: [...PHASES] },
          finished: { type: 'boolean', description: 'True once the flow is closed.' },
          tasks: {
            type: 'array',
            description:
              'The planned worker tasks in order, numbered from 1. Each title must equal the Agent tool `description` the task will be delegated with, so the panel can match runs to tasks.',
            items: {
              type: 'object',
              properties: {
                title: { type: 'string', description: 'A few words; reused verbatim as the Agent description.' },
                tier: { type: 'string', enum: ['fable', 'heavy', 'careful', 'medium', 'light', ...CREW] },
                after: { type: 'array', items: { type: 'integer' }, description: 'Numbers of the tasks this one waits for.' },
              },
              required: ['title', 'tier'],
            },
          },
        },
      },
    })
    await $.tool.register({
      name: 'step',
      description:
        'For savvy-flow workers: report progress on your own task to the agents panel. ' +
        'Right after reading the brief, call it with `total` (your plan in 3-8 steps) and `done: 0`; ' +
        'call it again as each step finishes. Cheap and silent: it only draws a bar.',
      inputSchema: {
        type: 'object',
        properties: {
          done: { type: 'integer', minimum: 0, description: 'Steps finished so far.' },
          total: { type: 'integer', minimum: 1, description: 'Steps planned; may change if the plan changes.' },
          note: { type: 'string', description: 'The step in progress, a few words.' },
        },
        required: ['done'],
      },
    })
    await $.command.register({
      name: 'agents-info',
      description: 'Show or hide the panel of subagents: running, finished and planned, with model, context, cost and time',
    })

    // Polls the background sessions, but only with the pane open or a flow's bar up: otherwise nothing runs.
    $.clock.every(BG_EVERY_MS, () => {
      void (async () => {
        const f = await read($, flow)
        if ((await $.ui.panes()).some(p => p.id === PANE) || (f && !f.isFinished)) await pollBg($)
      })()
    })

    $.clock.every(VIEW_EVERY_MS, () => {
      void (async () => {
        if ((await $.ui.panes()).some(p => p.id === VIEW_PANE && p.isShown)) await refreshView($)
      })()
    })

    // Ticks the running agents' clocks; quiet when nothing runs.
    $.clock.every(1000, () => {
      void (async () => {
        const list = await read($, agents)
        if (!list.some(a => a.status === 'running')) return
        const at = await $.clock.now()
        await update($, now, () => at)
      })()
    })
    // Flips the running crabs' pose; quiet unless the pane is open and something runs.
    $.clock.every(CRAB_EVERY_MS, () => {
      void (async () => {
        const isBusy = (await read($, agents)).some(a => a.status === 'running') || (await read($, bg)).some(b => b.state === 'busy')
        if (isBusy && (await $.ui.panes()).some(p => p.id === PANE)) await update($, frame, n => 1 - n)
      })()
    })
    return started
  })

  on('command.run', { command: 'agents-info' }, async $ => {
    const isOpen = await togglePane($)
    return { text: isOpen ? tr().opened : tr().closed }
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const input = e as unknown as ProgressInput
    const prev = await read($, flow)
    if (isNewFlow(prev, input) && input.title !== undefined) {
      // A new flow starts with a clean list; agents still running stay.
      await update($, agents, list => list.filter(a => a.status === 'running'))
    }
    const next = await update($, flow, p => merge(p, input))
    if (next && input.tasks?.length) await autoOpen($, next.title)
    return { result: `ok: ${label(next ?? blank())}` }
  })

  // A worker's own progress: the call runs in the worker's loop, so agentId names it.
  on('tool.call', { tool: STEP_TOOL }, async ($, e) => {
    const input = e as unknown as { done?: number; total?: number; note?: string }
    const agentId = e.agentId
    if (!agentId) return { result: 'ignored: only subagents report steps' }
    await update($, agents, list =>
      list.map(a => {
        if (a.agentId !== agentId) return a
        const total = Math.max(0, Math.round(input.total ?? a.stepTotal ?? 0))
        const done = Math.max(0, Math.round(input.done ?? a.stepDone ?? 0))
        return { ...a, stepTotal: total, stepDone: total ? Math.min(total, done) : done, stepNote: input.note?.trim() || undefined }
      }),
    )
    return { result: 'ok' }
  })

  // This session's own background launches: the only place their model, effort and agent can be learned.
  on('tool.call', { tool: ['Bash', 'PowerShell'] }, async ($, e, next) => {
    try {
      const found = bgLaunches(String(e.command ?? '')).filter(l => l.name)
      if (found.length) {
        await update($, launches, all => ({
          ...all,
          ...Object.fromEntries(found.map(l => [(l.name ?? '').toLowerCase(), { model: l.model, effort: l.effort, agent: l.agent }])),
        }))
      }
    } catch {
      // Only a label for the panel: never worth failing the call.
    }
    return next(e)
  })

  // Safety net: worker launches move the faint layer even if the orchestrator forgets to report.
  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    const type = String(e.subagent_type ?? '')
    if (!isCrew(type)) return next(e)

    await update($, flow, prev => {
      const base = prev && !prev.isFinished ? { ...blank(), ...prev } : blank()
      return { ...base, running: base.running + 1, phase: base.phase === 'plan' ? 'delegate' : base.phase }
    })
    try {
      return await next(e)
    } finally {
      await update($, flow, prev => (prev ? { ...prev, running: Math.max(0, prev.running - 1) } : prev))
    }
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (started.deny !== undefined) return started

    const at = await $.clock.now()
    await update($, agents, list => {
      const round = 1 + list.filter(a => norm(a.description) === norm(e.description) && e.description).length
      const run: AgentRun = {
        id: started.agentId ?? e.tool_use_id,
        agentId: started.agentId,
        type: e.subagentType,
        description: e.description,
        model: started.model,
        status: 'running',
        startedAt: at,
        contextTokens: 0,
        contextMax: windowOf(started.model),
        tokens: 0,
        costUsd: 0,
        steps: 0,
        round,
      }
      return [...list.filter(a => a.id !== run.id), run].slice(-200)
    })
    await update($, now, () => at)
    if (isCrew(e.subagentType)) {
      const f = await read($, flow)
      await autoOpen($, f && !f.isFinished ? f.title : 'savvy-flow')
    }
    return started
  })

  // Each model request of a subagent: live context, tokens and cost.
  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    const agentId = e.agentId
    const usage = result.usage
    if (!agentId || !usage) return result

    const model = usage.model || e.model
    await update($, agents, list =>
      list.map(a =>
        a.agentId !== agentId
          ? a
          : {
              ...a,
              model,
              effort: typeof e.effort === 'string' ? e.effort : a.effort,
              status: 'running',
              endedAt: undefined,
              contextTokens:
                (usage.input_tokens || 0) +
                (usage.cache_read_input_tokens || 0) +
                (usage.cache_creation_input_tokens || 0) +
                (usage.output_tokens || 0),
              contextMax: windowOf(model),
              tokens:
                a.tokens +
                (usage.input_tokens || 0) +
                (usage.output_tokens || 0) +
                (usage.cache_read_input_tokens || 0) +
                (usage.cache_creation_input_tokens || 0),
              costUsd: a.costUsd + costOf(model, usage),
              steps: a.steps + 1,
            },
      ),
    )
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const agentId = e.agentId
    if (agentId) {
      const at = await $.clock.now()
      await update($, agents, list =>
        list.map(a => {
          if (a.agentId !== agentId) return a
          // A run whose steps went unseen still gets the turn's own sum.
          const fallback = a.steps === 0 && e.usage
          return {
            ...a,
            status: e.reason === 'answer' ? 'done' : 'failed',
            endedAt: at,
            ...(fallback && e.usage
              ? {
                  model: e.usage.model || a.model,
                  tokens:
                    e.usage.input_tokens +
                    e.usage.output_tokens +
                    e.usage.cache_read_input_tokens +
                    e.usage.cache_creation_input_tokens,
                  costUsd: costOf(e.usage.model || a.model, e.usage),
                }
              : {}),
          }
        }),
      )
      await update($, now, () => at)
    }
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const s = tr()
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const list = await read($, agents)
    const sessions = await read($, bg)
    const f = await read($, flow)
    const p: Panel = await read($, panel)
    const at = Math.max(await read($, now), ...list.map(a => a.startedAt), 0)

    const running = list.filter(a => a.status === 'running').reverse()
    const finished = list.filter(a => a.status !== 'running').reverse()
    const planned = plannedOf(f, list)
    const t = totals(list, at)
    // The pane's title says "Agents"; inside, only the flow's own name.
    const title = f && !f.isFinished ? f.title : ''

    const toggleCompact = (
      <Button
        key="compact"
        label={p.isCompact ? s.expand : s.collapse}
        plain
        onPress={() => update($, panel, prev => ({ ...prev, isCompact: !prev.isCompact }))}
      />
    )
    const toggleDone = (
      <Button
        key="done"
        label={`${p.isDoneCollapsed ? '▸' : '▾'} ${s.finished} · ${finished.length}`}
        plain
        onPress={() => update($, panel, prev => ({ ...prev, isDoneCollapsed: !prev.isDoneCollapsed }))}
      />
    )
    const isEmpty = list.length === 0 && planned.length === 0 && sessions.length === 0
    // A row's name opens the view pane; the first nine also by digit while the pane holds the keys.
    let hot = 0
    const agentTarget = (a: AgentRun): ViewTarget | null =>
      a.agentId ? { kind: 'agent', id: a.agentId, name: a.description || a.type } : null
    const bgTarget = (b: BgSession): ViewTarget => ({ kind: 'bg', id: b.id, name: b.name, cwd: b.cwd })
    const viewButton = (target: ViewTarget | null, text: string) => {
      if (!target) return <Text bold wrap="truncate-end">{text}</Text>
      const n = ++hot
      return (
        <Button key={`view-${target.id}`} plain {...(n <= 9 ? { hotkey: String(n) } : {})} onPress={() => void openView($, target)}>
          <Text bold>{text}</Text>
        </Button>
      )
    }
    const desktopView = (target: ViewTarget | null) =>
      target && (
        <Button key={`view-${target.id}`} plain dimColor label={`${s.view} ${target.name} ›`} onPress={() => void openView($, target)} />
      )
    const summary = `≈${fmtCost(t.cost)}, ${fmtTokens(t.tokens)} ${s.tokensWord}, ${fmtTime(t.time)}`

    if (e.surface === 'desktop' && 'Svg' in ui) {
      const { Svg } = ui
      const W = Math.max(240, Math.min(900, (e.props.bodyColumns || 40) * 8 - 8))
      const section = (key: string, text: string) => (
        <Text key={key} dimColor>
          {text}
        </Text>
      )

      if (p.isCompact) {
        return (
          <Box flexDirection="column" gap={1}>
            <Svg source={compactSvg(W, list, planned, sessions, t)} alt={`${list.length + sessions.length} ${s.agentsCount}, ${summary}`} width={W} height={32} />
            {toggleCompact}
          </Box>
        )
      }
      return (
        <Box flexDirection="column">
          <Svg source={headerSvg(W, title, t)} alt={title ? `${title}: ${summary}` : summary} width={W} height={headerHeight(title)} />
          {toggleCompact}
          {isEmpty && <Text dimColor>{s.empty}</Text>}
          {running.length > 0 && section('h-run', `${s.running} · ${running.length}`)}
          {running.map(a => [
            <Svg key={a.id} source={agentSvg(W, a, at)} alt={`${a.description}: ${modelName(a.model)}, ${s.isRunning}`} width={W} height={66} />,
            desktopView(agentTarget(a)),
          ])}
          {finished.length > 0 && toggleDone}
          {!p.isDoneCollapsed &&
            finished.map(a => [
              <Svg key={a.id} source={agentSvg(W, a, at)} alt={`${a.description}: ${modelName(a.model)}, ${s.isFinished}`} width={W} height={66} />,
              desktopView(agentTarget(a)),
            ])}
          {sessions.length > 0 && section('h-bg', `${s.background} · ${sessions.length}`)}
          {sessions.map(b => [
            <Svg key={`bg-${b.id}`} source={bgSvg(W, b)} alt={`${b.name}: ${bgStateText(b)}`} width={W} height={46} />,
            desktopView(bgTarget(b)),
          ])}
          {planned.length > 0 && section('h-plan', `${s.planned} · ${planned.length}`)}
          {planned.map(pl => (
            <Svg key={`plan-${pl.n}`} source={plannedSvg(W, pl)} alt={`${pl.n}. ${pl.title}: ${s.isPlanned}`} width={W} height={46} />
          ))}
        </Box>
      )
    }

    // Terminal: the same content in text rows. Read here, not above, so only this surface redraws on a frame tick.
    const tick = await read($, frame)
    const cols = Math.max(24, e.props.bodyColumns || 40)
    // The crab takes SPRITE_W columns and a gap; on a narrow pane the old glyph stays.
    const hasCrab = cols >= 40
    const room = cols - (hasCrab ? SPRITE_W + 1 : 0)
    const barW = Math.max(6, Math.min(20, room - 34))
    const indent = hasCrab ? '' : '  '
    const withCrab = (key: string, costume: string, body: JSX.Element, isAnimated: boolean) =>
      hasCrab ? (
        <Box key={key} flexDirection="row" gap={1} marginBottom={1}>
          <Box flexDirection="column" flexShrink={0} width={SPRITE_W}>
            {crabLines(Text, spriteOf(costume, isAnimated ? tick : 0), key)}
          </Box>
          <Box flexDirection="column" justifyContent="center" width={room}>
            {body}
          </Box>
        </Box>
      ) : (
        <Box key={key} flexDirection="column" marginBottom={1}>
          {body}
        </Box>
      )
    const bgRow = (b: BgSession) => {
      const color = colorOf(b.tier)
      return withCrab(
        `bg-${b.id}`,
        b.tier,
        <>
          <Box flexDirection="row" gap={1}>
            {!hasCrab && <Text color={color}>▣</Text>}
            {viewButton(bgTarget(b), b.name)}
            <Text color={b.state === 'waiting' ? 'warning' : b.state === 'busy' ? color : undefined} dimColor={b.state === 'idle'}>
              {BG_GLYPH[b.state]}
            </Text>
          </Box>
          <Text dimColor wrap="truncate-end">
            {indent}
            {b.tier === 'other' ? s.session : b.tier} · {bgModel(b)}
          </Text>
          <Text dimColor wrap="truncate-end">
            {indent}
            {bgStateText(b)}
            {b.branch ? ` · ${b.branch}` : ''}
          </Text>
        </>,
        b.state === 'busy',
      )
    }
    const row = (a: AgentRun) => {
      const tier = tierOf(a.type)
      const color = colorOf(tier)
      const ctx = ctxOf(a)
      const progress = progressOf(a)
      const model = a.effort ? `${modelName(a.model)} · ${a.effort}` : modelName(a.model)
      const steps = a.stepTotal ? `${a.stepDone ?? 0}/${a.stepTotal}${a.stepNote ? ' ' + a.stepNote : ''} · ` : ''
      return withCrab(
        a.id,
        costumeOf(a.type),
        <>
          <Box flexDirection="row" gap={1}>
            {!hasCrab && <Text color={color}>▣</Text>}
            {viewButton(agentTarget(a), a.description || a.type)}
            <Text color={a.status === 'failed' ? 'red' : a.status === 'done' ? 'green' : color}>{STATUS_GLYPH[a.status]}</Text>
          </Box>
          <Text dimColor wrap="truncate-end">
            {indent}
            {tier === 'other' ? a.type : tier} · {model}
            {a.round > 1 ? ` · ${s.round} ${a.round}` : ''}
          </Text>
          <Text wrap="truncate-end">
            {indent}
            {progress === null ? <Text dimColor>{ctxBar(ctx, barW)}</Text> : <Text color={color}>{ctxBar(progress * 100, barW)}</Text>}
            <Text dimColor>
              {' '}
              {steps}ctx {ctx}% · {fmtTokens(a.contextTokens)} ≈{fmtCost(a.costUsd)} {fmtTime(elapsed(a, at))}
            </Text>
          </Text>
        </>,
        a.status === 'running',
      )
    }

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" justifyContent="space-between">
          <Text bold wrap="truncate-end">
            {title}
          </Text>
          {toggleCompact}
        </Box>
        <Text dimColor>
          ≈{fmtCost(t.cost)} · {fmtTokens(t.tokens)} {s.tokensWord} · {fmtTime(t.time)}
        </Text>
        {p.isCompact ? (
          <Text wrap="truncate-end">
            {sessions.map(b => (
              <Text key={`bg-${b.id}`} color={colorOf(b.tier)}>
                {BG_GLYPH[b.state]}{' '}
              </Text>
            ))}
            {[...running, ...finished].map(a => (
              <Text key={a.id} color={colorOf(tierOf(a.type))}>
                {STATUS_GLYPH[a.status]}{' '}
              </Text>
            ))}
            {planned.map(pl => (
              <Text key={`plan-${pl.n}`} dimColor>
                ◷{' '}
              </Text>
            ))}
          </Text>
        ) : (
          <Box flexDirection="column" marginTop={1}>
            {isEmpty && <Text dimColor>{s.empty}</Text>}
            {running.length > 0 && <Text dimColor>{s.running} · {running.length}</Text>}
            {running.map(row)}
            {finished.length > 0 && toggleDone}
            {!p.isDoneCollapsed && finished.map(row)}
            {sessions.length > 0 && <Text dimColor>{s.background} · {sessions.length}</Text>}
            {sessions.map(bgRow)}
            {planned.length > 0 && <Text dimColor>{s.planned} · {planned.length}</Text>}
            {planned.map(pl => {
              const tier = pl.tier in TIER_COLOR ? pl.tier : 'other'
              return (
                <Box key={`plan-${pl.n}`} flexDirection="column" marginBottom={1}>
                  <Text dimColor wrap="truncate-end">
                    <Text color={colorOf(tier)}>▢</Text> {pl.n}. {pl.title} ◷
                  </Text>
                  <Text dimColor wrap="truncate-end">
                    {'  '}
                    {tier} · {TIER_MODEL[tier] ?? ''}
                    {pl.after.length ? ` · ${s.after} ${pl.after.join(', ')}` : ''}
                  </Text>
                </Box>
              )
            })}
          </Box>
        )}
      </Box>
    )
  })

  // The person scrolling the view pane: at the end it follows new lines, anywhere above it stays put.
  on('ui.scroll', { component: 'Pane', requestId: VIEW_PANE }, async ($, e, next) => {
    const moved = await next(e)
    if (!moved.deny) {
      const isAtEnd = e.offset >= e.contentRows - e.bodyRows
      if ((await read($, viewFollow)) !== isAtEnd) await update($, viewFollow, () => isAtEnd)
    }
    return moved
  })

  // One subagent's or background session's latest lines, newest at the bottom: a header with its state and
  // model, a rule, then prompts, replies and tool calls styled the way the transcript draws them.
  on('ui.render', { component: 'Pane', requestId: VIEW_PANE }, async ($, e) => {
    const s = tr()
    const { Box, Text } = $.ui.resolve(e)
    const v = await read($, view)
    if (!v) return <Text dimColor>{s.viewEmpty}</Text>
    const cols = Math.max(20, e.props.bodyColumns || 60)

    // The header, from the row the panel holds for it.
    let glyph = ''
    let glyphColor: string | undefined
    let state = ''
    let meta: string[] = []
    if (v.kind === 'bg') {
      const b = (await read($, bg)).find(x => x.id === v.id)
      if (b) {
        glyph = BG_GLYPH[b.state]
        glyphColor = b.state === 'waiting' ? 'warning' : b.state === 'busy' ? colorOf(b.tier) : undefined
        state = bgStateText(b)
        meta = [b.tier === 'other' ? s.session : b.tier, bgModel(b), b.branch ?? '']
      }
    } else {
      const a = (await read($, agents)).find(x => x.agentId === v.id)
      if (a) {
        const tier = tierOf(a.type)
        glyph = STATUS_GLYPH[a.status] ?? ''
        glyphColor = a.status === 'failed' ? 'red' : a.status === 'done' ? 'green' : colorOf(tier)
        state = a.status === 'running' ? s.isRunning : a.status === 'done' ? s.isFinished : s.failed
        meta = [tier === 'other' ? a.type : tier, a.effort ? `${modelName(a.model)} · ${a.effort}` : modelName(a.model)]
      }
    }
    const header = [
      <Box key="h-name" flexDirection="row" gap={1}>
        <Text bold wrap="truncate-end">
          {v.name}
        </Text>
        {glyph && <Text color={glyphColor}>{glyph}</Text>}
        {state && <Text dimColor>{state}</Text>}
      </Box>,
      meta.filter(Boolean).length > 0 && (
        <Text key="h-meta" dimColor wrap="truncate-end">
          {meta.filter(Boolean).join(' · ')}
        </Text>
      ),
      v.kind === 'bg' && (
        <Text key="h-attach" dimColor wrap="truncate-end">
          {s.attach} <Text color={ACCENT}>claude attach {v.id.slice(0, 8)}</Text>
          {v.source === 'logs' ? ` · ${s.fromLogs}` : ''}
        </Text>
      ),
      <Text key="h-keys" dimColor wrap="truncate-end">
        {(await read($, viewFollow)) ? s.scrollHint : s.scrollBack}
      </Text>,
      <Text key="h-rule" dimColor>
        {'─'.repeat(cols)}
      </Text>,
    ].filter(Boolean)

    // ponytail: the last VIEW_MAX_ROWS rows (of a background session, of its transcript's last 3.5 MB);
    // `claude attach` has the whole session.
    const tail = wrapLines(v.lines, cols - 2).slice(-VIEW_MAX_ROWS)
    while (tail[0]?.kind === 'gap') tail.shift()
    const line = (l: ViewLine, i: number) => {
      const key = `l${i}`
      if (l.kind === 'gap') return <Text key={key}> </Text>
      if (l.kind === 'tool' || l.kind === 'pending' || l.kind === 'error') {
        const mark = l.kind === 'error' ? '✗' : l.kind === 'pending' ? '◌' : '⎿'
        const color = l.kind === 'error' ? 'red' : l.kind === 'pending' ? 'warning' : DONE
        return (
          <Text key={key} wrap="truncate-end">
            <Text color={color}>{mark} </Text>
            {l.tool && <Text bold>{l.tool} </Text>}
            <Text dimColor>{l.text}</Text>
          </Text>
        )
      }
      if (l.kind === 'user')
        return (
          <Text key={key} wrap="truncate-end" color={ACCENT}>
            {l.isCont ? '  ' : '❯ '}
            {l.text}
          </Text>
        )
      if (l.kind === 'log')
        return (
          <Text key={key} wrap="truncate-end">
            {l.text || ' '}
          </Text>
        )
      return (
        <Text key={key} wrap="truncate-end">
          {l.isCont ? '  ' : '● '}
          {l.text || ' '}
        </Text>
      )
    }
    return (
      <Box flexDirection="column">
        {header}
        {tail.length === 0 ? <Text dimColor>{s.viewEmpty}</Text> : tail.map(line)}
      </Box>
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const f = await read($, flow)
    if (f === null || e.props.hasSurvey) return next(e)

    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const list = await read($, agents)
    const crew = list.length + plannedOf(f, list).length + (await read($, bg)).length
    const isWorking = list.some(a => a.status === 'running')
    const crewButton = (
      <Button key="savvy-agents" label={`×${crew}`} plain onPress={() => void togglePane($)} />
    )
    const percent = `${Math.round(ratio(f) * 100)}%`
    const dismiss = (
      <Button
        key="savvy-dismiss"
        label="✕"
        plain
        role="dismiss"
        onPress={() => update($, flow, () => null)}
      />
    )

    if (e.surface === 'desktop' && 'Svg' in ui) {
      const { Svg } = ui
      // About 8 CSS px per reported column; the rest is the count, the dismiss
      // and their gaps. No floor above the slot: a row wider than it would wrap.
      const width = Math.max(180, Math.min(1600, (e.props.bodyColumns || 100) * 8 - 96))
      return (
        <Box flexDirection="row" alignItems="center" gap={1}>
          <Svg source={rowSvg(f, width, isWorking)} alt={`${f.title}: ${label(f)}, ${percent}`} width={width} height={H} />
          {crewButton}
          {dismiss}
        </Box>
      )
    }

    const cols = e.props.bodyColumns
    const titleW = Math.max(8, Math.min(30, f.title.length + 2, Math.floor(cols / 3)))
    const width = Math.max(6, Math.min(40, cols - titleW - 32))
    return (
      <Box flexDirection="row" gap={2} alignItems="center">
        <Box width={titleW} flexShrink={0}>
          <Text color={f.isFinished ? DONE : ACCENT}>● </Text>
          <Text wrap="truncate-end">{f.title}</Text>
        </Box>
        <Text color={f.isFinished ? DONE : ACCENT}>{barText(f, width)}</Text>
        <Text bold>{label(f)}</Text>
        <Text dimColor>{percent}</Text>
        <Box flexDirection="column" flexShrink={0}>
          {crabLines(Text, spriteOf('orchestrator'), 'band')}
        </Box>
        {crewButton}
        {dismiss}
      </Box>
    )
  })
}

